/**
 * Configuration options for the DefiLlama client.
 */
interface DefiLlamaConfig {
    /**
     * Pro API key for accessing premium endpoints.
     * Get your key at https://defillama.com/pro-api
     */
    apiKey?: string;
    /**
     * Request timeout in milliseconds.
     * @default 30000
     */
    timeout?: number;
}
type BaseUrl = "main" | "v2" | "bridges" | "coins" | "stablecoins";
declare class BaseClient {
    private apiKey?;
    private timeout;
    constructor(config?: DefiLlamaConfig);
    get hasApiKey(): boolean;
    getApiKey(): string | undefined;
    private buildUrl;
    private handleResponse;
    get<T>(endpoint: string, options?: {
        params?: Record<string, string | number | boolean | undefined>;
        requiresAuth?: boolean;
        base?: BaseUrl;
        apiNamespace?: string;
    }): Promise<T>;
    post<T>(endpoint: string, body: unknown, options?: {
        requiresAuth?: boolean;
        base?: BaseUrl;
        apiNamespace?: string;
    }): Promise<T>;
}

